import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Laravel SaaS Kit Configuration","description":"The .env keys and config files that control tenancy, authentication, permissions, translations and queues in the SaaS Laravel starter kits.","frontmatter":{"title":"Laravel SaaS Kit Configuration","description":"The .env keys and config files that control tenancy, authentication, permissions, translations and queues in the SaaS Laravel starter kits.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/getting-started/configuration.html"}],["meta",{"property":"og:title","content":"Laravel SaaS Kit Configuration"}],["meta",{"property":"og:description","content":"The .env keys and config files that control tenancy, authentication, permissions, translations and queues in the SaaS Laravel starter kits."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/getting-started/configuration.html"}],["meta",{"name":"twitter:title","content":"Laravel SaaS Kit Configuration"}],["meta",{"name":"twitter:description","content":"The .env keys and config files that control tenancy, authentication, permissions, translations and queues in the SaaS Laravel starter kits."}]]},"headers":[],"relativePath":"docs/getting-started/configuration.md","filePath":"docs/getting-started/configuration.md","lastUpdated":1790486087000}'),o={name:"docs/getting-started/configuration.md"};function i(n,e,r,c,h,l){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Most settings are standard Laravel. This page covers the keys and files that are specific to the kits. For every <code>.env</code> key and its default, see the <a href="/docs/reference/environment.html">Environment reference</a>.</p><h2 id="key-env-values" tabindex="-1">Key <code>.env</code> values <a class="header-anchor" href="#key-env-values" aria-label="Permalink to &quot;Key `.env` values&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Example (Vue kit)</th><th>Used for</th></tr></thead><tbody><tr><td><code>APP_URL</code></td><td><code>http://vue.test</code></td><td>Fortify passkeys, and the scheme (<code>http</code> / <code>https</code>) of tenant links</td></tr><tr><td><code>APP_DOMAIN</code></td><td><code>vue.test</code></td><td>The central domain, and the suffix for tenant subdomains</td></tr><tr><td><code>DB_CONNECTION</code>, <code>DB_DATABASE</code></td><td><code>mysql</code>, <code>saas_laravel_vue</code></td><td>Central database; tenant databases are created on the same server</td></tr><tr><td><code>SESSION_DRIVER</code></td><td><code>database</code></td><td>Sessions</td></tr><tr><td><code>QUEUE_CONNECTION</code></td><td><code>database</code></td><td>Queued emails and jobs</td></tr><tr><td><code>CACHE_STORE</code></td><td><code>database</code></td><td>Cache</td></tr><tr><td><code>MAIL_MAILER</code></td><td><code>log</code></td><td>Writes emails to the log until you configure a real mailer</td></tr></tbody></table><p>Where the database-backed drivers store their data:</p><table tabindex="0"><thead><tr><th>Driver</th><th>Central domain</th><th>Tenant domain</th></tr></thead><tbody><tr><td>Sessions</td><td>Central <code>sessions</code> table</td><td>That tenant&#39;s <code>sessions</code> table (sessions use the active connection)</td></tr><tr><td>Cache</td><td>Central <code>cache</code> table</td><td>Tenant databases have their own <code>cache</code> tables</td></tr><tr><td>Queue</td><td>Central <code>jobs</code> table</td><td>Also the central <code>jobs</code> table (see <a href="#config-queue-php"><code>config/queue.php</code></a>)</td></tr></tbody></table><h2 id="config-tenancy-php" tabindex="-1"><code>config/tenancy.php</code> <a class="header-anchor" href="#config-tenancy-php" aria-label="Permalink to &quot;`config/tenancy.php`&quot;">​</a></h2><p><code>APP_DOMAIN</code> is read here twice: as <code>central_domains</code> (a single-item array) and as <code>domain</code> (the suffix for tenant subdomains).</p><table tabindex="0"><thead><tr><th>Key</th><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>tenant_model</code></td><td><code>App\\Models\\Tenant</code></td><td>Integer auto-increment IDs</td></tr><tr><td><code>domain_model</code></td><td><code>App\\Models\\Domain</code></td><td>Adds <code>is_primary</code>, <code>app_name</code>, <code>locale</code>, <code>auth_features</code></td></tr><tr><td><code>central_domains</code></td><td><code>[env(&#39;APP_DOMAIN&#39;)]</code></td><td>Requests on any other host initialize tenancy</td></tr><tr><td><code>domain</code></td><td><code>env(&#39;APP_DOMAIN&#39;)</code></td><td>Tenant domains are <code>&lt;sub&gt;.&lt;domain&gt;</code></td></tr><tr><td><code>bootstrappers</code></td><td>Database, Cache, Filesystem, Queue</td><td>Redis bootstrapper is commented out</td></tr><tr><td><code>database.central_connection</code></td><td><code>env(&#39;DB_CONNECTION&#39;, &#39;central&#39;)</code></td><td></td></tr><tr><td><code>database.prefix</code></td><td><code>&#39;tenant&#39;</code> (React: <code>env(&#39;TENANCY_DB_PREFIX&#39;, &#39;tenant&#39;)</code>)</td><td>Tenant DB name = prefix + tenant id</td></tr><tr><td><code>database.managers</code></td><td>sqlite, mysql, mariadb, pgsql</td><td></td></tr><tr><td><code>filesystem.disks</code></td><td><code>local</code>, <code>public</code></td><td>Suffixed per tenant (<code>storage/tenant&lt;id&gt;/...</code>)</td></tr><tr><td><code>migration_parameters</code></td><td><code>--path =&gt; database/migrations/tenant</code></td><td>Used by <code>tenants:migrate</code></td></tr><tr><td><code>seeder_parameters</code></td><td><code>--class =&gt; TenantDatabaseSeeder</code></td><td>Used by <code>tenants:seed</code> and tenant creation</td></tr></tbody></table><p>See <a href="/docs/core/database.html#tenant-database-naming">Database → Tenant database naming</a> before changing the prefix.</p><h2 id="config-fortify-php" tabindex="-1"><code>config/fortify.php</code> <a class="header-anchor" href="#config-fortify-php" aria-label="Permalink to &quot;`config/fortify.php`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Value</th></tr></thead><tbody><tr><td><code>guard</code> / <code>passwords</code></td><td><code>web</code> / <code>central_users</code> (switched to <code>tenant</code> / <code>tenant_users</code> on tenant domains)</td></tr><tr><td><code>home</code></td><td><code>/dashboard</code></td></tr><tr><td><code>lowercase_usernames</code></td><td><code>true</code></td></tr><tr><td><code>features</code></td><td><code>registration</code>, <code>resetPasswords</code>, <code>emailVerification</code>, <code>twoFactorAuthentication</code> (confirm + confirmPassword), <code>passkeys</code> (confirmPassword)</td></tr><tr><td><code>passkeys.relying_party_id</code></td><td>Host of <code>APP_URL</code></td></tr><tr><td><code>passkeys.user_handle_secret</code></td><td><code>env(&#39;PASSKEYS_USER_HANDLE_SECRET&#39;, config(&#39;app.key&#39;))</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">The feature list is the maximum</p><p>Tenant domains can switch individual features off, but never on if they are missing here. See <a href="/docs/core/authentication.html#per-domain-features">Authentication → Per-domain features</a>.</p></div><h2 id="config-auth-php" tabindex="-1"><code>config/auth.php</code> <a class="header-anchor" href="#config-auth-php" aria-label="Permalink to &quot;`config/auth.php`&quot;">​</a></h2><p>Two session guards share <code>App\\Models\\User</code>:</p><table tabindex="0"><thead><tr><th>Guard</th><th>Provider</th><th>Password broker</th></tr></thead><tbody><tr><td><code>web</code></td><td><code>central_users</code></td><td><code>central_users</code></td></tr><tr><td><code>tenant</code></td><td><code>tenant_users</code></td><td><code>tenant_users</code></td></tr></tbody></table><p><code>AUTH_PASSWORD_TIMEOUT</code> (default <code>10800</code> seconds) controls how long a password confirmation lasts.</p><h2 id="config-permission-php-and-config-permissions" tabindex="-1"><code>config/permission.php</code> and <code>config/permissions/*</code> <a class="header-anchor" href="#config-permission-php-and-config-permissions" aria-label="Permalink to &quot;`config/permission.php` and `config/permissions/*`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>config/permission.php</code></td><td>Standard spatie config: teams disabled, wildcard permissions disabled, 24-hour cache</td></tr><tr><td><code>config/permissions/*.php</code></td><td>Central permissions and the default system roles for each</td></tr><tr><td><code>config/permissions/tenant/*.php</code></td><td>Tenant permissions and the default system roles for each</td></tr></tbody></table><p>Each file becomes one permission group in the UI; the file name is the group key. File format and examples: <a href="/docs/core/users-roles-permissions.html#permissions">Users, roles &amp; permissions → Permissions</a>.</p><h2 id="config-inertia-lang-php" tabindex="-1"><code>config/inertia-lang.php</code> <a class="header-anchor" href="#config-inertia-lang-php" aria-label="Permalink to &quot;`config/inertia-lang.php`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Value</th></tr></thead><tbody><tr><td><code>lang_path</code></td><td><code>base_path(&#39;lang&#39;)</code></td></tr><tr><td><code>output_lang</code></td><td><code>resource_path(&#39;js/lang&#39;)</code></td></tr></tbody></table><p><code>php artisan erag:generate-lang</code> exports PHP translation files from <code>lang_path</code> to JSON in <code>output_lang</code>. See <a href="/docs/core/localization.html">Localization</a>.</p><h2 id="config-queue-php" tabindex="-1"><code>config/queue.php</code> <a class="header-anchor" href="#config-queue-php" aria-label="Permalink to &quot;`config/queue.php`&quot;">​</a></h2><p>All queued jobs, including those dispatched inside a tenant, are stored in the <strong>central</strong> <code>jobs</code> table, so a single worker processes them for every tenant.</p><p>This works because the <code>database</code> queue connection reads <code>DB_QUEUE_CONNECTION</code>, which defaults to <code>DB_CONNECTION</code> (the central connection name, e.g. <code>mysql</code>), not the tenant connection. stancl&#39;s <code>QueueTenancyBootstrapper</code> restores the tenant context when each job runs.</p><details class="details custom-block"><summary>View the queue connection</summary><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;database&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;driver&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;database&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;connection&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;DB_QUEUE_CONNECTION&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;DB_CONNECTION&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)),</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;table&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;DB_QUEUE_TABLE&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;jobs&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;queue&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;DB_QUEUE&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;default&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;retry_after&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;DB_QUEUE_RETRY_AFTER&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">90</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div></details><p>More: <a href="/docs/getting-started/local-development.html#queue-worker">Local development → Queue worker</a>.</p><h2 id="other-files" tabindex="-1">Other files <a class="header-anchor" href="#other-files" aria-label="Permalink to &quot;Other files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Notes</th></tr></thead><tbody><tr><td><code>config/app.php</code></td><td><code>locale</code> / <code>fallback_locale</code> from <code>APP_LOCALE</code> / <code>APP_FALLBACK_LOCALE</code> (<code>en</code>)</td></tr><tr><td><code>config/data.php</code></td><td>spatie/laravel-data defaults</td></tr><tr><td><code>config/inertia.php</code></td><td>Inertia server settings</td></tr><tr><td><code>bootstrap/app.php</code></td><td>Middleware registration, aliases (<code>auth</code>, <code>guest</code>, <code>central.only</code>, <code>permission</code>, <code>role</code>) and error page rendering</td></tr><tr><td><code>bootstrap/providers.php</code></td><td>App and module service providers</td></tr></tbody></table>',30)])])}const k=t(o,[["render",i]]);export{g as __pageData,k as default};
